export { AStart, NodeAStar, buildNetwork } from './AStar';
export class Graph {
    public nodes: Node[] = [];
    public edges: Edge[] = [];
    public nodeOrigin: Node;
    public nodeTarget: Node;
    public constructor() {

    }
    public initByLines(lns: {}) {
        this.nodes = [];
        this.edges = [];
        this.AddEdgeByLines(lns);
    }
    public AddEdgeByLines(lns: any) {
        let nodes: Node[] = [];
        for (let i = 0; i < lns.length; ++i) {
            let p0 = lns[i].p0;
            let p1 = lns[i].p1;
            nodes.push(this.AddNode(p0));
            nodes.push(this.AddNode(p1));
        }
        for (let i = 0; i < nodes.length; i += 2) {
            this.AddEdge(nodes[i], nodes[i + 1]);
        }
    }
    public AddNode(p: any ): Node {
        for (let i = 0; i < this.nodes.length; ++i) {
            if (this.distanceTo(p.x, p.y, p.z, this.nodes[i].x, this.nodes[i].y, this.nodes[i].z) < 0.01) {
                return this.nodes[i];
            }
        }

        let node = new Node(p.x, p.y, p.z);
        node.id = this.nodes.length;
        this.nodes.push(node);
        return node;
    }
    public AddEdge(n1: Node, n2: Node): Edge | undefined {
        if (n1 === n2) return undefined;

        const testedEdge = this.findEdge(n1, n2);
        if (testedEdge !== undefined) {
            return testedEdge;
        }

        let edge = new Edge(n1, n2);
        edge.id = this.edges.length;
        this.edges.push(edge);
        return edge;
    }
    // ..............................................................
    public findEdge(n0: Node, n1: Node): Edge | undefined {
        for (let i = 0; i < this.edges.length; ++i) {
            if ((this.edges[i].n0 === n0 && this.edges[i].n1 === n1) || (this.edges[i].n0 === n1 && this.edges[i].n1 === n0)) {
                return this.edges[i];
            }
        }
        return undefined;
    }
    public findClosestNode(p: any): Node | undefined {
        if (this.nodes.length === 0) return undefined;
        let index = -1;
        let disMin = Number.MAX_VALUE;
        for (let i = 0; i < this.nodes.length; ++i) {
            let d = this.distanceTo(p.x, p.y, p.z, this.nodes[i].x, this.nodes[i].y, this.nodes[i].z);
            if (d < disMin) {
                index = i;
                disMin = d;
            }
        }
        return this.nodes[index];
    }
    public distanceTo (x0: number, y0: number, z0: number, x1: number, y1: number, z1: number): number {
        return Math.sqrt((x0 - x1) * (x0 - x1) + (y0 - y1) * (y0 - y1) + (z0 - z1) * (z0 - z1));
    }
    // ..............................................................
    public costFnDistance = (p0: Node, p1: Node, beta: number = 0.0002) => {
        return this.distanceTo(p0.x, p0.y, p0.z, p1.x, p1.y, p1.z);
    }
    public propagationByNode(origin: Node, optimizer?: (current: Node, np: Node, Beta: number) => number | undefined , Beta: number = 1) { //, PixelMap pMap, transitionCostDelegate cost) {
       if(optimizer === undefined) {
        optimizer = this.costFnDistance;
       }

       this.nodeOrigin = origin;

       for(let i = 0; i < this.nodes.length; ++i) { this.nodes[i].reset(); }

        let queue: Node[] = [];
        queue.push(origin);
        for (let i = 0; i < 10000000; ++i) {
            if (queue.length === 0) { break; }
            let current: Node = queue[0];

            queue.shift();
            for (let j = 0; j < current.nodes.length; ++j) {
                let np: Node = current.nodes[j];
                let newCost = optimizer(current, np, Beta) ?? 0;
                let result = (current.networkDistance + newCost);
                let newTemp = result; /// this.UNIT_VALUE; // result < 0.001 ? result  : result / this.UNIT_VALUE;
                if (np.networkDistance === -1.0 || newTemp < np.networkDistance) {
                    np.networkDistance = newTemp;
                    queue.push(np);
                }
            }
        }
    }
    public backpropagation(destination: Node): Node[] {
        let j = 0; let k = 0;
        this.nodeTarget = destination;

        let path: Node[] = [];
        if (destination.networkDistance !== -1.0) {
            path.push(this.nodes[destination.id]);
            let current: Node = destination;
            for (j = 0; j < 100000; ++j) {
                let smallest: Node = current;
                smallest.countVisit++;

                for (k = 0; k < current.nodes.length; ++k) {
                    let np: Node = current.nodes[k];
                    if (np.networkDistance < smallest.networkDistance) {
                        smallest = np;
                    }
                }

                if (smallest === current) {
                    path.push(this.nodeOrigin); // start node
                    break;
                }
                current = smallest;
                path.push(this.nodes[current.id]);

            }
    
        }
        return path;
    }

}
export class Edge {
    public id: number = -1;
    public n0: Node;
    public n1: Node;

    constructor(n0: Node, n1: Node) {
        this.n0 = n0;
        this.n1 = n1;
        this.n0.edges.push(this);
        this.n1.edges.push(this);
        n0.nodes.push(n1);
        n1.nodes.push(n0);
    }
}
export class Node {
    public id: number = -1;
    public x: number;
    public y: number;
    public z: number;

    public edges: Edge[] = [];
    public nodes: Node[] = [];

    public networkDistance: number = -1;
    public countVisit: number = 0;

    constructor(x: number, y: number, z: number) {
        this.x = x;
        this.y = y;
        this.z = z;
    }
    public reset(): void {
        this.networkDistance = -1;
        this.countVisit = 0;
    }
    public deepCopy(): Node {
        let n = new Node(this.x, this.y, this.z);
        n.id = this.id;
        return n;
    }
}


